function Toggle({label,hint,checked,onChange,disabled}:{label:string;hint?:string;checked:boolean;onChange:(v:boolean)=>void;disabled?:boolean}){return <label className="studio-toggle"><span><strong>{label}</strong>{hint&&<small>{hint}</small>}</span><input type="checkbox" checked={checked} disabled={disabled} onChange={e=>onChange(e.target.checked)}/><i aria-hidden="true"/></label>}
