 const [edgeSource,setEdgeSource]=useState(''),[edgeTarget,setEdgeTarget]=useState(''),[edgeLabel,setEdgeLabel]=useState('');
 const [working,setWorking]=useState(false),[error,setError]=useState(''),[toast,setToast]=useState(''),[pending,setPending]=useState<Pending|null>(null);
 const [executing,setExecuting]=useState(false),[runOpen,setRunOpen]=useState(false),[nodeOpen,setNodeOpen]=useState(false),[nodeStates,setNodeStates]=useState<Record<string,string>>({}),[remoteReady,setRemoteReady]=useState<boolean|null>(null);
