 const catalogScopeKey=`${agent?.id||''}|${user?.id||''}|${draftAgentId}|${draftBaseUrl}`;catalogScope.current=catalogScopeKey;
 const modelSuggestions=[...new Set([...Object.entries(MODELS).filter(([,config])=>config.chat).map(([id])=>id),...modelCatalog.modelIds])];
 useEffect(()=>{catalogSequence.current++;catalogController.current?.abort();catalogController.current=null;setModelCatalog({status:'idle',modelIds:[],message:''});return()=>{catalogSequence.current++;catalogController.current?.abort()}},[catalogScopeKey]);
 useEffect(()=>{setNodeStates({})},[agent?.id,definition?.revision]);
 async function reload(){const id=++request.current;setLoadError('');try{const result=await service.load();if(request.current===id)setRaw(result)}catch(e:any){if(request.current===id)setLoadError(e.message||'Could not load the shared workspace.')}finally{if(request.current===id)setLoading(false)}}
 useEffect(()=>{reload();const unsubscribe=service.subscribe(reload);return()=>{request.current++;unsubscribe()}},[]);
 useEffect(()=>{onDirtyChange?.(dirty);return()=>onDirtyChange?.(false)},[dirty,onDirtyChange]);
 useEffect(()=>{onSavingChange?.(busy);return()=>onSavingChange?.(false)},[busy,onSavingChange]);
 useEffect(()=>{let mounted=true;getRuntimeConfig().then(config=>{if(mounted)setRemoteReady(config.remoteAvailable!==false)});return()=>{mounted=false}},[]);
 useEffect(()=>{if(!dirty)return;const before=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue=''};window.addEventListener('beforeunload',before);return()=>window.removeEventListener('beforeunload',before)},[dirty]);
 useEffect(()=>{if(!agent||!definition)return;const next=configurationFrom(agent,definition),json=JSON.stringify(next);if(draftAgentId!==agent.id||(!dirtyRef.current&&json!==baseline)){setDraft(next);setBaseline(json);setDraftAgentId(agent.id);setNodeId(id=>next.definition.nodes.some(n=>n.id===id)?id:next.definition.nodes.find(n=>n.kind==='Agent')?.id||next.definition.nodes[0]?.id||null);setError('')}},[agent,definition,draftAgentId,baseline]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(timer)},[toast]);
 function change(update:(value:AgentConfiguration)=>void){if(!writable||busy)return;setDraft(current=>{if(!current)return current;const next=structuredClone(current);update(next);return next});setError('');setToast('')}
 function resetDraft(){if(!agent||!definition)return;const next=configurationFrom(agent,definition);setDraft(next);setBaseline(JSON.stringify(next));setDraftAgentId(agent.id);setError('');setEdgeSource('');setEdgeTarget('');setEdgeLabel('');setNodeId(next.definition.nodes.find(n=>n.kind==='Agent')?.id||next.definition.nodes[0]?.id||null)}
 function perform(target:Pending){setPending(null);if(target.type==='discard'){resetDraft();setToast('Draft changes discarded. The saved configuration is restored.');return}if(target.type==='govern'){onGovern(target.id||agent!.id,target.runId);return}setRunOpen(!!target.openRun);if(target.openRun){setSection('Graph');setQuery('')}setNodeOpen(false);setNodeStates({});setDraft(null);setBaseline('');setDraftAgentId('');setError('');setToast('');setNodeId(null);setEdgeSource('');setEdgeTarget('');setEdgeLabel('');if(target.type==='role'){setUserId(target.id!);setSelectedId('')}else setSelectedId(target.id!);scroll.current?.scrollTo({top:0})}
 function navigate(target:Pending){if(busy)return;if(dirty)setPending(target);else perform(target)}
 async function save(){if(!draft||!agent||!user||!writable||busy)return;setWorking(true);setError('');try{await service.saveAgentConfiguration(agent.id,draft,user.id);const next=await service.load();setRaw(next);const nextAgent=next.agents.find(a=>a.id===agent.id),nextDefinition=next.definitions.find(d=>d.agentId===agent.id);if(nextAgent&&nextDefinition){const conf=configurationFrom(nextAgent,nextDefinition);setDraft(conf);setBaseline(JSON.stringify(conf));setDraftAgentId(agent.id);setToast(`Revision ${nextDefinition.revision} saved. Agent governance now uses the same configuration.`)}}catch(e:any){setError(e.message||'Could not save this configuration. Your draft is preserved.');if(/revision|changed|conflict|reload/i.test(e.message||''))await reload()}finally{setWorking(false)}}
 function openNode(id:string){if(executing)return;setNodeId(id);setNodeOpen(true)}
 function executionState(running:boolean){setExecuting(running);if(running)setNodeStates({})}
 function executionProgress(id:string,status:string){setNodeStates(previous=>({...previous,[id]:status}))}
 function exportDefinition(){if(!draft||!agent)return;const blob=new Blob([JSON.stringify({agentId:agent.id,mode:service.mode,saved:!dirty,...draft},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${agent.id}-configuration.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);setToast(`${dirty?'Draft':'Saved'} configuration exported.`)}
 function addNode(){const id=uid('node');change(d=>{d.definition.nodes.push({id,label:`New ${nodeKind.toLowerCase()}`,kind:nodeKind,description:'Describe this node’s responsibility.',prompt:'',enabled:true,...(nodeKind==='Tool'?{toolName:d.agent.tools[0]||TOOL_NAMES[0]}:{})})});setNodeId(id);setGraphView('graph')}
 function updateNode(value:Partial<AgentNode>){if(!nodeId)return;change(d=>{const node=d.definition.nodes.find(n=>n.id===nodeId);if(node)Object.assign(node,value)})}
 function deleteNode(){if(!nodeId||!writable||busy)return;change(d=>{d.definition.nodes=d.definition.nodes.filter(n=>n.id!==nodeId);d.definition.edges=d.definition.edges.filter(e=>e.source!==nodeId&&e.target!==nodeId)});setEdgeSource(value=>value===nodeId?'':value);setEdgeTarget(value=>value===nodeId?'':value);setNodeOpen(false);setNodeId(null);setToast('Node and its connections removed from the draft. Save to apply.')}
 function addEdge(){if(!edgeSource||!edgeTarget)return;if(edgeSource===edgeTarget){setError('Choose two different nodes for a connection.');return}if(draft?.definition.edges.some(e=>e.source===edgeSource&&e.target===edgeTarget)){setError('These nodes are already connected.');return}change(d=>d.definition.edges.push({id:uid('edge'),source:edgeSource,target:edgeTarget,label:edgeLabel.trim()||'Continue'}));setEdgeTarget('');setEdgeLabel('')}
 function toggleTool(tool:string,enabled:boolean){change(d=>{d.agent.tools=enabled?[...new Set([...d.agent.tools,tool])]:d.agent.tools.filter(t=>t!==tool);if(!enabled)d.definition.nodes.forEach(n=>{if(n.kind==='Tool'&&n.toolName===tool)n.enabled=false})})}
 function guardrailChange(id:string,value:Partial<Guardrail>){change(d=>{const guard=d.definition.guardrails.find(g=>g.id===id);if(guard)Object.assign(guard,value)})}
 function chooseModel(name:string){change(d=>{const previousBaseUrl=d.definition.model.baseUrl??agentBaseUrl(d.definition.model);d.definition.model={...d.definition.model,provider:'Nebius',name,baseUrl:modelConfig(name)?.baseUrl||previousBaseUrl}})}
