 const executionRequest=agent&&definition?{agent,definition,...(store.globalPolicies?{globalPolicies:{revision:store.globalPolicies.revision,rules:store.globalPolicies.rules}}:{}),references:(store.definitions.filter(d=>definition.nodes.some(n=>n.referencedAgentId===d.agentId)).map(d=>({agent:store.agents.find(a=>a.id===d.agentId)!,definition:d}))).filter(r=>!!r.agent)}:null;
